import { useState } from "react";
import { Link } from "react-router-dom";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { Cloud, Shield, ChevronRight, Scan, Download, Github, Loader2, AlertCircle } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { Progress } from "@/components/ui/progress";
import { useToast } from "@/hooks/use-toast";
import { scanIaC, postureScore, CSPM_RULE_COUNT, type CspmFinding } from "@/lib/cloud-cspm/engine";
import { parseRepoUrl, fetchRepoFiles } from "@/lib/ai-assessment/github-client";

const SEV: Record<string, string> = {
  critical: "bg-red-500/15 text-red-400 border-red-500/30",
  high: "bg-orange-500/15 text-orange-400 border-orange-500/30",
  medium: "bg-amber-500/15 text-amber-400 border-amber-500/30",
  low: "bg-blue-500/15 text-blue-400 border-blue-500/30",
};

const IAC_EXT = /\.(tf|yaml|yml|json)$/i;

export default function CloudCSPM() {
  const { toast } = useToast();
  const [input, setInput] = useState("");
  const [repoInput, setRepoInput] = useState("");
  const [findings, setFindings] = useState<CspmFinding[]>([]);
  const [scanned, setScanned] = useState(false);
  const [scanning, setScanning] = useState(false);
  const [scanSource, setScanSource] = useState("");

  const score = scanned ? postureScore(findings) : null;

  const runScanOnText = (text: string, source: string) => {
    if (!text.trim()) {
      toast({ title: "No IaC content", description: "Paste Terraform/YAML or scan a GitHub repo.", variant: "destructive" });
      return;
    }
    setFindings(scanIaC(text));
    setScanSource(source);
    setScanned(true);
  };

  const runPasteScan = () => runScanOnText(input, "pasted content");

  const runRepoScan = async () => {
    const parsed = parseRepoUrl(repoInput);
    if (!parsed) {
      toast({ title: "Invalid repo", variant: "destructive" });
      return;
    }
    setScanning(true);
    try {
      const files = await fetchRepoFiles(parsed.owner, parsed.repo, "main");
      const iacFiles = files.filter((f) => IAC_EXT.test(f.path) || f.path.endsWith("Dockerfile"));
      if (iacFiles.length === 0) {
        toast({ title: "No IaC files found", description: "Repository has no .tf/.yaml files to scan.", variant: "destructive" });
        return;
      }
      const combined = iacFiles.map((f) => `# ${f.path}\n${f.content}`).join("\n\n");
      setInput(combined.slice(0, 120_000));
      runScanOnText(combined, `${parsed.owner}/${parsed.repo} (${iacFiles.length} files)`);
    } catch (e) {
      toast({ title: "Scan failed", description: e instanceof Error ? e.message : "Could not fetch repo", variant: "destructive" });
    } finally {
      setScanning(false);
    }
  };

  const exportReport = () => {
    if (!scanned) return;
    const md = `# CSPM Posture Report
Source: ${scanSource}
Score: ${score}/100
Findings: ${findings.length}
Generated: ${new Date().toISOString()}

${findings.map((f) =>
  `## ${f.title} (${f.severity})
- Provider: ${f.provider}
- Resource: ${f.resource}${f.line ? `\n- Line: ${f.line}` : ""}
- Fix: ${f.recommendation}
- Compliance: ${f.compliance.join(", ")}`,
).join("\n\n")}`;
    const blob = new Blob([md], { type: "text/markdown" });
    const a = document.createElement("a");
    a.href = URL.createObjectURL(blob);
    a.download = `cspm-report-${new Date().toISOString().slice(0, 10)}.md`;
    a.click();
  };

  return (
    <div className="container mx-auto px-4 py-8 max-w-6xl">
      <div className="mb-6 flex items-center gap-2 text-xs text-muted-foreground">
        <Link to="/hub" className="hover:text-cyan-400">Platform Hub</Link>
        <ChevronRight className="h-3 w-3" />
        <Link to="/company/cloud-security" className="hover:text-cyan-400">Cloud Security</Link>
        <ChevronRight className="h-3 w-3" />
        <span className="text-sky-400">CSPM Scanner</span>
      </div>

      <div className="flex items-start gap-4 mb-8">
        <div className="flex h-12 w-12 items-center justify-center rounded-xl bg-gradient-to-br from-sky-400 to-blue-600">
          <Cloud className="h-6 w-6 text-white" />
        </div>
        <div>
          <h1 className="text-2xl font-bold">Multi-Cloud CSPM Scanner</h1>
          <p className="text-sm text-muted-foreground mt-1">
            Real pattern analysis on your IaC — {CSPM_RULE_COUNT} rules · no fabricated findings
          </p>
        </div>
      </div>

      <div className="grid gap-6 lg:grid-cols-3">
        <div className="lg:col-span-2 space-y-4">
          <Card>
            <CardHeader className="pb-2">
              <CardTitle className="text-sm flex items-center gap-2">
                <Github className="h-4 w-4" /> Scan GitHub repository
              </CardTitle>
            </CardHeader>
            <CardContent className="flex gap-2">
              <Input
                placeholder="owner/repo or GitHub URL"
                value={repoInput}
                onChange={(e) => setRepoInput(e.target.value)}
                className="font-mono text-sm"
              />
              <Button onClick={runRepoScan} disabled={scanning || !repoInput.trim()}>
                {scanning ? <Loader2 className="h-4 w-4 animate-spin" /> : <Scan className="h-4 w-4" />}
              </Button>
            </CardContent>
          </Card>

          <Card>
            <CardHeader className="pb-2">
              <CardTitle className="text-sm">Or paste IaC directly</CardTitle>
            </CardHeader>
            <CardContent className="space-y-3">
              <Textarea
                value={input}
                onChange={(e) => setInput(e.target.value)}
                placeholder="Paste Terraform, Kubernetes YAML, or CloudFormation…"
                rows={12}
                className="font-mono text-xs"
              />
              <Button onClick={runPasteScan} disabled={!input.trim()}>
                <Scan className="h-4 w-4 mr-1.5" /> Scan pasted content
              </Button>
            </CardContent>
          </Card>

          {scanned && (
            <Card>
              <CardHeader className="pb-2 flex flex-row items-center justify-between">
                <CardTitle className="text-sm">Findings ({findings.length})</CardTitle>
                <Button variant="ghost" size="sm" onClick={exportReport}>
                  <Download className="h-4 w-4 mr-1" /> Export
                </Button>
              </CardHeader>
              <CardContent className="space-y-3 max-h-[420px] overflow-y-auto">
                {scanSource && (
                  <p className="text-xs text-muted-foreground flex items-center gap-1">
                    <AlertCircle className="h-3 w-3" /> Source: {scanSource}
                  </p>
                )}
                {findings.length === 0 ? (
                  <p className="text-sm text-emerald-400 flex items-center gap-2">
                    <Shield className="h-4 w-4" /> No rule matches in scanned content
                  </p>
                ) : findings.map((f) => (
                  <div key={f.id} className="rounded-lg border border-white/5 p-3 bg-white/[0.02]">
                    <div className="flex justify-between gap-2">
                      <p className="text-sm font-medium">{f.title}</p>
                      <Badge variant="outline" className={SEV[f.severity]}>{f.severity}</Badge>
                    </div>
                    <p className="text-xs text-muted-foreground mt-1">
                      {f.provider.toUpperCase()} · {f.resource}{f.line ? ` · line ${f.line}` : ""}
                    </p>
                    <p className="text-xs text-cyan-400/80 mt-2">{f.recommendation}</p>
                  </div>
                ))}
              </CardContent>
            </Card>
          )}
        </div>

        <div className="space-y-4">
          <Card className="border-sky-500/20">
            <CardContent className="pt-6 text-center">
              <p className="text-xs uppercase tracking-widest text-muted-foreground">Posture score</p>
              <p className={`text-5xl font-bold mt-2 ${score == null ? "text-slate-600" : score >= 70 ? "text-emerald-400" : score >= 40 ? "text-amber-400" : "text-red-400"}`}>
                {score ?? "—"}
              </p>
              {score != null && <Progress value={score} className="mt-4 h-2" />}
              {!scanned && (
                <p className="text-xs text-muted-foreground mt-3">Run a scan to compute score from real matches</p>
              )}
            </CardContent>
          </Card>
        </div>
      </div>
    </div>
  );
}
